  }).map(el => {
    const parentContainer = el.closest('tr') || el.closest('[data-testid]') || el.parentElement?.parentElement?.parentElement;
    const varText = parentContainer?.innerText?.match(/变体\s*\(\d+\)/)?.[0] || 'N/A';
    const asinMatch = parentContainer?.innerText?.match(/B0[0-9A-Z]{8}/)?.[0] || 'N/A';
    const titleMatch = parentContainer?.querySelector('a[href*="/dp/"]')?.innerText || 'N/A';
    return {
      sku: el.innerText.trim(),
      parentAsin: asinMatch,
      variationCount: varText,
      title: titleMatch
    };
  });

  // Deduplicate by sku
  const unique = [];
  const seen = new Set();
  for (const item of parentMatches) {
    if (!seen.has(item.sku)) {
      seen.add(item.sku);
      unique.push(item);
    }
  }
  return unique;
