() => {
  const title = document.querySelector('#productTitle')?.innerText?.trim();
  const twister = document.querySelector('#twister, #twisterContainer, #variation_color_name, #variation_style_name, #variation_size_name, #variation_number_of_items');
  const variationDimensions = Array.from(document.querySelectorAll('[id*="variation_"]')).map(el => {
    return {
      id: el.id,
      text: el.innerText.trim().slice(0, 200)
    };
  });

  const options = Array.from(document.querySelectorAll('#twister li, [data-csa-c-item-id], .swatchAvailable, [data-defaultasin]')).map(li => {
    return {
      title: li.getAttribute('title') || li.innerText.trim(),
      asin: li.getAttribute('data-defaultasin') || li.getAttribute('data-csa-c-item-id')
    };
  }).filter(o => o.title || o.asin);

  const price = document.querySelector('.a-price .a-offscreen')?.innerText?.trim() || document.querySelector('#priceblock_ourprice')?.innerText?.trim();
  const reviews = document.querySelector('#acrCustomerReviewText')?.innerText?.trim();
  const stars = document.querySelector('#acrPopover')?.getAttribute('title')?.trim();

  return {
    title,
    price,
    reviews,
    stars,
    hasTwister: !!twister,
    variationDimensions,
    optionsCount: options.length,
    optionsSnippet: options.slice(0, 15)
  };
}

